#include <algorithm>
#include <iostream>
#include <memory>
struct Node{int value;std::unique_ptr<Node>left,right;};
int height(const Node*n){return n?1+std::max(height(n->left.get()),height(n->right.get())):0;}
bool leaf(const Node*n){return n&&!n->left&&!n->right;}
int main(){Node root{1,std::make_unique<Node>(Node{2}),std::make_unique<Node>(Node{3})};std::cout<<height(&root)<<' '<<std::boolalpha<<leaf(root.left.get())<<'\n';}

#include <iostream>
struct Node{int v;Node*l{};Node*r{};};
void pre(Node*n){if(!n)return;std::cout<<n->v;pre(n->l);pre(n->r);}void in(Node*n){if(!n)return;in(n->l);std::cout<<n->v;in(n->r);}void post(Node*n){if(!n)return;post(n->l);post(n->r);std::cout<<n->v;}
int main(){Node a{2},b{1},c{3};a.l=&b;a.r=&c;pre(&a);std::cout<<' ';in(&a);std::cout<<' ';post(&a);std::cout<<'\n';}
